// Baustein 4: Ergebnis je Mail -> Ziel-Label bestimmen (v0.8)
// schreiben / dublette -> FinVault/Verarbeitet, fehler -> FinVault/Fehler
const labels = $('Gmail: Labels holen').all().map(i => i.json);
