// Baustein 4: Log-Zeilen (JSON Lines) für System/Automation/patreon-import-log.jsonl (v0.8)
const now = new Date().toISOString();
const lines = $('Ergebnis je Mail').all().map(i => JSON.stringify({
  timestamp: now,
  workflow: 'FinVault Patreon → Vault v0.8',
  gmail_message_id: i.json.gmail_message_id,
  betreff: i.json.subject,
  ergebnis: i.json.action,
  ziel_label: i.json.ziel_label,
  datei: i.json.action === 'schreiben' ? i.json.info : '',
  hinweis: i.json.action !== 'schreiben' ? i.json.info : '',
  ticker: i.json.ticker || '',
  abbildungen: i.json.abbildungen || 0,
  kosten_cent: i.json.kosten_cent || 0,
}));
const text = lines.join('\n') + '\n';
return [{ json: { zeilen: lines.length }, binary: { data: { data: Buffer.from(text, 'utf8').toString('base64'), mimeType: 'application/x-ndjson', fileName: 'patreon-import-log.jsonl' } } }];
